/* Own minimal Borlabs Cookie v3 simulator for integration tests (no vendor code). Mimics public identifiers only:
   window.BorlabsCookie, #BorlabsCookieBox .brlbs-cmpnt-dialog, .brlbs-btn-* classes, cookie "borlabs-cookie".
   `sim.details`: the services the collapsed Cookie-Details list with provider and purpose, next to the visitor's UID. */
(function () {
  var cfg = (window.borlabsCookieConfig && window.borlabsCookieConfig.sim) || {};
  // A new UID per visit, as a consent ID is; it starts with the marker `zq7` that no snapshot may contain.
  function part(n) { var s = ''; while (s.length < n) s += Math.random().toString(36).slice(2); return s.slice(0, n); }
  var uid = 'zq7' + part(5) + '-' + part(8) + '-' + part(8) + '-' + part(8);
  function detailsHtml(list) {
    var tables = '';
    for (var i = 0; i < list.length; i++) {
      var d = list[i];
      tables += '<table class="brlbs-cmpnt-cookie-table"><tbody>' +
        '<tr><th>Name</th><td>' + d.name + '</td></tr>' +
        '<tr><th>Anbieter</th><td>' + d.provider + '</td></tr>' +
        '<tr><th>Zweck</th><td>' + d.purpose + '</td></tr>' +
        '<tr><th>Datenschutzerklärung</th><td>' + d.policy + '</td></tr>' +
        '<tr><th>Cookie Name</th><td>' + d.cookies + '</td></tr>' +
        '<tr><th>Cookie Laufzeit</th><td>' + d.lifetime + '</td></tr>' +
        '</tbody></table>';
    }
    return '<div class="brlbs-cmpnt-cookie-details" style="display:none"><h3>Cookie-Details</h3>' + tables +
      '<p>Ihre Einwilligungs-ID (UID): <span class="brlbs-uid">' + uid + '</span></p></div>';
  }
  var GROUPS = { essential: ['borlabs-cookie'], statistics: ['google-analytics'], marketing: ['facebook-pixel'], 'external-media': ['youtube'] };
  function getCookie(name) {
    var parts = document.cookie.split(';');
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i].trim();
      if (p.indexOf(name + '=') === 0) return decodeURIComponent(p.slice(name.length + 1));
    }
    return null;
  }
  function save(all) {
    var consents = { essential: GROUPS.essential };
    if (all) { consents.statistics = GROUPS.statistics; consents.marketing = GROUPS.marketing; consents['external-media'] = GROUPS['external-media']; }
    var v = JSON.stringify({ consents: consents, domainPath: location.host + '/', expires: 'Fri, 30 Oct 2027 00:00:00 GMT', uid: 'anonymous', v3: true, version: 1 });
    document.cookie = 'borlabs-cookie=' + encodeURIComponent(v) + '; path=/; max-age=31536000; SameSite=Lax';
  }
  var stored = getCookie('borlabs-cookie');
  var consents = stored ? JSON.parse(stored).consents : null;
  window.BorlabsCookie = {
    Consents: {
      hasConsent: function (serviceId) {
        if (!consents) return false;
        for (var g in consents) if (consents[g].indexOf(serviceId) >= 0) return true;
        return false;
      }
    }
  };
  var isBot = /bot|googlebot|crawler|spider|robot|crawling|lighthouse/i.test(navigator.userAgent);
  if (stored) return;
  if (isBot && window.borlabsCookieConfig.settings.cookiesForBots) { save(true); return; }
  if (window.borlabsCookieConfig.settings.dialogHideDialogOnPages.indexOf(location.href.split('?')[0]) >= 0) return;

  var box = document.createElement('div');
  box.id = 'BorlabsCookieBox';
  box.innerHTML =
    '<div class="brlbs-cmpnt-dialog-backdrop" style="position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:999998"></div>' +
    '<div class="brlbs-cmpnt-dialog" role="dialog" aria-modal="true" aria-labelledby="brlbs-title" style="position:fixed;z-index:999999;top:50%;left:50%;transform:translate(-50%,-50%);width:520px;background:#fff;color:#222;padding:24px;font:15px/1.4 sans-serif;border-radius:6px">' +
    '<h2 id="brlbs-title" style="margin-top:0">Datenschutzeinstellungen</h2>' +
    '<p>Wir nutzen Cookies auf unserer Website. Einige von ihnen sind essenziell, während andere uns helfen, diese Website und Ihre Erfahrung zu verbessern.</p>' +
    '<p><a href="/datenschutz.html">Datenschutzerklärung</a> | <a href="/impressum.html">Impressum</a></p>' +
    '<div style="display:flex;flex-direction:column;gap:8px">' +
    '<button type="button" class="brlbs-btn brlbs-btn-accept-all" style="padding:10px;background:#0063e3;color:#fff;border:0">Alle akzeptieren</button>' +
    (cfg.reject ? '<button type="button" class="brlbs-btn brlbs-btn-accept-only-essential" style="padding:10px;background:#0063e3;color:#fff;border:0">Nur essenzielle Cookies akzeptieren</button>' : '') +
    '<a href="#" class="brlbs-cmpnt-link" role="button" style="color:#0063e3">Individuelle Datenschutzeinstellungen</a>' +
    (cfg.details ? '<a href="#" class="brlbs-cmpnt-link brlbs-cookie-details-link" role="button" style="color:#0063e3">Cookie-Details</a>' : '') +
    '</div>' + (cfg.details ? detailsHtml(cfg.details) : '') + '</div>';
  function show() {
    document.body.appendChild(box);
    document.documentElement.style.overflow = 'hidden';
    function close(all) {
      save(all);
      box.remove();
      document.documentElement.style.overflow = '';
      consents = JSON.parse(getCookie('borlabs-cookie')).consents;
    }
    box.querySelector('.brlbs-btn-accept-all').addEventListener('click', function () { close(true); });
    var ess = box.querySelector('.brlbs-btn-accept-only-essential');
    if (ess) ess.addEventListener('click', function () { close(false); });
    var detailsLink = box.querySelector('.brlbs-cookie-details-link');
    if (detailsLink) detailsLink.addEventListener('click', function (ev) {
      ev.preventDefault();
      var d = box.querySelector('.brlbs-cmpnt-cookie-details');
      d.style.display = d.style.display === 'none' ? 'block' : 'none';
    });
  }
  if (document.body) show(); else document.addEventListener('DOMContentLoaded', show);
})();
